INSERT INTO master_produk (kode_produk,nama_produk,tipe_produk,satuan,harga_jual,stok_terkini,stok_minimal,default_iterasi,eligible_member_discount,is_active,hpp_per_unit,pajak_persen,komisi_dokter_tipe,komisi_dokter_value,kandungan,golongan,kekuatan_nilai,kekuatan_satuan) VALUES
('OBM-075','Metcor 8mg','RETAIL','tablet',8500,0,5,0,0,1,5189,11.00,'PERSEN_MARGIN',5.00,'Methylprednisolone','KORTIKOSTEROID',8,'mg')
ON DUPLICATE KEY UPDATE harga_jual=VALUES(harga_jual), hpp_per_unit=VALUES(hpp_per_unit), kekuatan_nilai=VALUES(kekuatan_nilai), kekuatan_satuan=VALUES(kekuatan_satuan), golongan=VALUES(golongan);

SELECT COUNT(*) AS topikal_ada_hpp FROM master_produk WHERE kode_produk LIKE 'TPK-%' AND hpp_per_unit>0;
SELECT COUNT(*) AS obat_ada_hpp FROM master_produk WHERE kode_produk LIKE 'OBM-%' AND hpp_per_unit>0;
SELECT COUNT(*) AS obat_ada_kekuatan FROM master_produk WHERE kode_produk LIKE 'OBM-%' AND kekuatan_nilai IS NOT NULL;
SELECT COUNT(*) AS topikal_ada_isi FROM master_produk WHERE kode_produk LIKE 'TPK-%' AND isi_kemasan IS NOT NULL;
